#include <algorithm>
#include <iostream>
#include <limits>
#include <vector>

const long long INF = std::numeric_limits<long long>::max() / 4;

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n, m, q;
    std::cin >> n >> m >> q;
    std::vector<std::vector<long long>> d(n, std::vector<long long>(n, INF));
    for (int v = 0; v < n; ++v) d[v][v] = 0;
    for (int i = 0; i < m; ++i) {
        int u, v;
        long long w;
        std::cin >> u >> v >> w;
        d[u - 1][v - 1] = std::min(d[u - 1][v - 1], w);
    }

    for (int k = 0; k < n; ++k)                 // the intermediate vertex, outermost
        for (int i = 0; i < n; ++i)
            for (int j = 0; j < n; ++j)
                if (d[i][k] + d[k][j] < d[i][j]) d[i][j] = d[i][k] + d[k][j];

    for (int i = 0; i < q; ++i) {
        int a, b;
        std::cin >> a >> b;
        long long answer = d[a - 1][b - 1];
        std::cout << (answer >= INF ? -1 : answer) << '\n';
    }
}
